namespace ymccPrivateBinding {
using Json=nlohmann::json;
struct Handle {HANDLE h=INVALID_HANDLE_VALUE;Handle()=default;explicit Handle(HANDLE v):h(v){}~Handle(){if(h!=INVALID_HANDLE_VALUE)CloseHandle(h);}Handle(const Handle&)=delete;Handle& operator=(const Handle&)=delete;};
inline std::string utf8(const std::wstring& w){const auto n=WideCharToMultiByte(CP_UTF8,0,w.c_str(),int(w.size()),nullptr,0,nullptr,nullptr);std::string out(n,'\0');if(n)WideCharToMultiByte(CP_UTF8,0,w.c_str(),int(w.size()),out.data(),n,nullptr,nullptr);return out;}
inline std::wstring wide(const std::string& s){const auto n=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s.data(),int(s.size()),nullptr,0);if(!n)throw std::runtime_error("lease-path-encoding");std::wstring out(n,L'\0');MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s.data(),int(s.size()),out.data(),n);return out;}
inline std::string digest(HANDLE file){BCRYPT_ALG_HANDLE alg=nullptr;BCRYPT_HASH_HANDLE hash=nullptr;auto cleanup=[&](){if(hash)BCryptDestroyHash(hash);if(alg)BCryptCloseAlgorithmProvider(alg,0);};
 if(BCryptOpenAlgorithmProvider(&alg,BCRYPT_SHA256_ALGORITHM,nullptr,0)<0||BCryptCreateHash(alg,&hash,nullptr,0,nullptr,0,0)<0){cleanup();throw std::runtime_error("lease-sha-init");}
 LARGE_INTEGER zero{};if(!SetFilePointerEx(file,zero,nullptr,FILE_BEGIN)){cleanup();throw std::runtime_error("lease-seek");}BYTE block[65536],out[32];DWORD n=0;
 for(;;){if(!ReadFile(file,block,sizeof(block),&n,nullptr)){cleanup();throw std::runtime_error("lease-read");}if(!n)break;if(BCryptHashData(hash,block,n,0)<0){cleanup();throw std::runtime_error("lease-sha-data");}}
 if(BCryptFinishHash(hash,out,32,0)<0){cleanup();throw std::runtime_error("lease-sha-finish");}cleanup();static const char hex[]="0123456789abcdef";std::string result;for(const auto b:out){result+=hex[b>>4];result+=hex[b&15];}return result;}
inline std::string readText(HANDLE h){LARGE_INTEGER zero{},size{};if(!GetFileSizeEx(h,&size)||size.QuadPart<0||size.QuadPart>16*1024*1024||!SetFilePointerEx(h,zero,nullptr,FILE_BEGIN))throw std::runtime_error("lease-text-size");std::string text(size_t(size.QuadPart),'\0');DWORD got=0;if(!ReadFile(h,text.data(),DWORD(text.size()),&got,nullptr)||got!=text.size())throw std::runtime_error("lease-text-read");return text;}
struct Lease {
 std::set<std::wstring> directories;std::vector<std::unique_ptr<Handle>> held;std::map<std::wstring,std::string> known;Json rows=Json::array();std::wstring ticket;std::string ticketHash;unsigned long long readBytes=0;Json timing=Json::array();
 static std::wstring key(std::wstring value){for(auto& c:value)c=wchar_t(towlower(c));return value;}
 void lockParents(const std::wstring& p){for(auto dir=std::filesystem::path(p).parent_path();!dir.empty();){const auto k=key(dir.wstring());if(directories.insert(k).second){auto h=std::make_unique<Handle>(CreateFileW(dir.c_str(),FILE_READ_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE,nullptr,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS|FILE_FLAG_OPEN_REPARSE_POINT,nullptr));BY_HANDLE_FILE_INFORMATION info{};if(h->h==INVALID_HANDLE_VALUE||!GetFileInformationByHandle(h->h,&info)||!(info.dwFileAttributes&FILE_ATTRIBUTE_DIRECTORY)||(info.dwFileAttributes&FILE_ATTRIBUTE_REPARSE_POINT))throw std::runtime_error("lease-directory-lock");held.push_back(std::move(h));}const auto next=dir.parent_path();if(next==dir)break;dir=next;}}
 HANDLE pin(const std::wstring& p,const std::string& expected){auto k=key(p);const auto found=known.find(k);if(found!=known.end()){if(found->second!=expected)throw std::runtime_error("lease-pin-conflict");return INVALID_HANDLE_VALUE;}
  lockParents(p);if(!ymccPrivateRun::plainPath(p,false))throw std::runtime_error("lease-reparse-or-nondisk-path");auto handle=std::make_unique<Handle>(CreateFileW(p.c_str(),GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_FLAG_OPEN_REPARSE_POINT|FILE_FLAG_SEQUENTIAL_SCAN,nullptr));
  if(handle->h==INVALID_HANDLE_VALUE||GetFileType(handle->h)!=FILE_TYPE_DISK)throw std::runtime_error("lease-readonly-lock");BY_HANDLE_FILE_INFORMATION before{},after{};if(!GetFileInformationByHandle(handle->h,&before)||before.dwFileAttributes&FILE_ATTRIBUTE_REPARSE_POINT)throw std::runtime_error("lease-file-info");
  const auto actual=digest(handle->h);if(actual!=expected)throw std::runtime_error("lease-content-pin");if(!GetFileInformationByHandle(handle->h,&after)||before.dwVolumeSerialNumber!=after.dwVolumeSerialNumber||before.nFileIndexHigh!=after.nFileIndexHigh||before.nFileIndexLow!=after.nFileIndexLow||before.nFileSizeHigh!=after.nFileSizeHigh||before.nFileSizeLow!=after.nFileSizeLow||CompareFileTime(&before.ftLastWriteTime,&after.ftLastWriteTime))throw std::runtime_error("lease-content-drift");
  const auto bytes=(static_cast<unsigned long long>(after.nFileSizeHigh)<<32)|after.nFileSizeLow;readBytes+=bytes;rows.push_back(Json{{"path",utf8(p)},{"sha256",actual},{"bytes",bytes},{"volume",after.dwVolumeSerialNumber},{"fileIndexHigh",after.nFileIndexHigh},{"fileIndexLow",after.nFileIndexLow}});known.emplace(k,actual);const auto result=handle->h;held.push_back(std::move(handle));return result;
 }
 void checkpoint(const char* stage){timing.push_back(Json{{"stage",stage},{"realTickMs",::GetTickCount64()},{"leaseFiles",rows.size()},{"leaseReadBytes",readBytes}});std::ofstream out(std::filesystem::path(ymccPrivateRun::bound.root)/L"timing-checkpoints.json",std::ios::binary|std::ios::trunc);out<<timing.dump();if(!out)throw std::runtime_error("timing-checkpoint-write");}
 explicit Lease(const std::wstring& dll){checkpoint("before-binding-lease");const auto manifest=std::filesystem::path(dll).parent_path()/L"fixture-manifest.json";const auto expected=utf8(ymccPrivateRun::env(L"YMCC_PRIVATE_MANIFEST_SHA256"));if(expected.size()!=64)throw std::runtime_error("lease-manifest-pin-env");const auto m=pin(manifest.wstring(),expected);const auto data=Json::parse(readText(m));if(data.value("status","")!="BUILT")throw std::runtime_error("lease-manifest-status");const auto& inputs=data.at("inputBindings");
  for(const auto& row:inputs.at("sources")){const auto hash=row.at("sha256").get<std::string>();pin(wide(row.at("path").get<std::string>()),hash);pin(wide(row.at("snapshot").get<std::string>()),hash);}
  for(const auto& row:inputs.at("generatedInputs"))pin(wide(row.at("path").get<std::string>()),row.at("sha256").get<std::string>());
  for(const auto& row:data.at("runtimeArtifacts"))pin(wide(row.at("path").get<std::string>()),row.at("sha256").get<std::string>());
  // Exact existing framework allowlist members only; no runtime directory wildcard/inventory.
  for(const auto& row:inputs.at("toolchainAllowlist")){const auto p=wide(row.at("path").get<std::string>());if(key(p).find(L"\\dotnet\\shared\\microsoft.netcore.app\\")!=std::wstring::npos)pin(p,row.at("sha256").get<std::string>());}
  ticket=ymccPrivateRun::bound.root+L"\\managed-bindings-lease.json";const Json proof{{"kind","NATIVE_OWNED_READONLY_BINDING_LEASE_V1"},{"parentPid",GetCurrentProcessId()},{"manifestSha256",expected},{"inputManifestSha256",data.at("inputManifestSha256")},{"files",rows},{"byteReads",readBytes},{"immutability","Native parent holds GENERIC_READ / FILE_SHARE_READ without write/delete sharing through child lifetime"}};const auto text=proof.dump();
  auto output=std::make_unique<Handle>(CreateFileW(ticket.c_str(),GENERIC_READ|GENERIC_WRITE,0,nullptr,CREATE_NEW,FILE_FLAG_OPEN_REPARSE_POINT|FILE_FLAG_WRITE_THROUGH,nullptr));DWORD wrote=0;if(output->h==INVALID_HANDLE_VALUE||!WriteFile(output->h,text.data(),DWORD(text.size()),&wrote,nullptr)||wrote!=text.size()||!FlushFileBuffers(output->h))throw std::runtime_error("lease-proof-create");ticketHash=digest(output->h);output.reset();pin(ticket,ticketHash);checkpoint("after-binding-lease");
 }
};
static std::unique_ptr<Lease> invocation;
inline void initialize(const std::wstring& dll){if(invocation)throw std::runtime_error("lease-invocation-reentry");invocation=std::make_unique<Lease>(dll);}
inline void checkpoint(const char* stage){if(!invocation)throw std::runtime_error("lease-not-ready");invocation->checkpoint(stage);}
inline std::vector<wchar_t> environment(std::vector<wchar_t> old){if(!invocation)throw std::runtime_error("lease-not-ready");std::vector<std::wstring> vars;for(size_t i=0;i<old.size()&&old[i];){vars.emplace_back(old.data()+i);i+=vars.back().size()+1;}vars.push_back(L"YMCC_PRIVATE_BINDING_LEASE="+invocation->ticket);vars.push_back(L"YMCC_PRIVATE_BINDING_LEASE_SHA256="+wide(invocation->ticketHash));vars.push_back(L"YMCC_PRIVATE_MANIFEST_SHA256="+ymccPrivateRun::env(L"YMCC_PRIVATE_MANIFEST_SHA256"));std::sort(vars.begin(),vars.end(),[](const auto&a,const auto&b){return _wcsicmp(a.c_str(),b.c_str())<0;});std::vector<wchar_t> block;for(const auto&v:vars){block.insert(block.end(),v.begin(),v.end());block.push_back(0);}block.push_back(0);return block;}
}

using System.IO;using System.Security.Cryptography;using System.Text.Json;
internal static class PrivateBindingLease {
 private sealed record OwnedHash(FileStream Stream,string Hash);
 private static readonly Dictionary<string,OwnedHash> Local=new(StringComparer.OrdinalIgnoreCase);
 private static readonly Dictionary<string,string> Leased=new(StringComparer.OrdinalIgnoreCase);
 private static FileStream? Ticket;private static ParentProcessLifetime? Parent;private static string TicketHash="";private static long LocalBytes,LocalHashes,LeaseHits;
 internal static string Hash(string path){
  if(Volatile.Read(ref DisposalStarted)!=0)throw new ObjectDisposedException(nameof(PrivateBindingLease));var hashStarted=System.Diagnostics.Stopwatch.GetTimestamp();try{
  path=Path.GetFullPath(path);
  if(Parent is { IsAlive:true }&&Ticket is not null&&Leased.TryGetValue(path,out var protectedHash)){++LeaseHits;return protectedHash;}
  if(Local.TryGetValue(path,out var cached))return cached.Hash;
  // A fallback path is hashed for real and held without write/delete sharing until this child exits.
  var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read,65536,FileOptions.SequentialScan);try{var bytes=stream.Length;var hash=Convert.ToHexString(SHA256.HashData(stream)).ToLowerInvariant();Local.Add(path,new(stream,hash));LocalBytes+=bytes;++LocalHashes;return hash;}catch{stream.Dispose();throw;}
  }finally{PrivateRuntimeTiming.RecordHash(hashStarted);}
 }
 internal static void Initialize(int parentPid){
  if(Volatile.Read(ref DisposalStarted)!=0)throw new ObjectDisposedException(nameof(PrivateBindingLease));
  if(Ticket is not null)throw new InvalidDataException("binding-lease-reentry");var root=Environment.GetEnvironmentVariable("YMCC_PRIVATE_RUN_ROOT")??"";var supplied=Environment.GetEnvironmentVariable("YMCC_PRIVATE_BINDING_LEASE")??"";var expected=Environment.GetEnvironmentVariable("YMCC_PRIVATE_BINDING_LEASE_SHA256")??"";var manifest=Environment.GetEnvironmentVariable("YMCC_PRIVATE_MANIFEST_SHA256")??"";
  if(expected.Length!=64||manifest.Length!=64||!string.Equals(Path.GetFullPath(supplied),Path.Combine(root,"managed-bindings-lease.json"),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("binding-lease-path-pin");
  PrivateRuntimeTiming.Mark("lease-proof-open-begin");var file=new FileStream(supplied,FileMode.Open,FileAccess.Read,FileShare.Read);PrivateRuntimeTiming.Mark("lease-proof-open-end");try{PrivateRuntimeTiming.Mark("lease-proof-sha-begin");TicketHash=Convert.ToHexString(SHA256.HashData(file)).ToLowerInvariant();PrivateRuntimeTiming.Mark("lease-proof-sha-end");if(TicketHash!=expected)throw new InvalidDataException("binding-lease-proof-changed");file.Position=0;PrivateRuntimeTiming.Mark("lease-proof-json-begin");using var proof=JsonDocument.Parse(file);var p=proof.RootElement;PrivateRuntimeTiming.Mark("lease-proof-json-end");
   if(p.GetProperty("kind").GetString()!="NATIVE_OWNED_READONLY_BINDING_LEASE_V1"||p.GetProperty("parentPid").GetInt32()!=parentPid||p.GetProperty("manifestSha256").GetString()!=manifest||p.GetProperty("inputManifestSha256").GetString()!=ManagedFixtureIdentity.InputManifestSha256)throw new InvalidDataException("binding-lease-parent-manifest");
   PrivateRuntimeTiming.Mark("lease-parent-open-begin");Parent=ParentProcessLifetime.TryOpen(parentPid);PrivateRuntimeTiming.Mark("lease-parent-open-end");if(Parent is null||!Parent.IsAlive)throw new InvalidDataException("binding-lease-parent-not-live");
   PrivateRuntimeTiming.Mark("lease-proof-rows-begin");foreach(var row in p.GetProperty("files").EnumerateArray()){var path=Path.GetFullPath(row.GetProperty("path").GetString()!);var hash=row.GetProperty("sha256").GetString()!;if(hash.Length!=64||!Leased.TryAdd(path,hash))throw new InvalidDataException("binding-lease-duplicate-row");}
   Ticket=file;PrivateRuntimeTiming.Mark("lease-proof-rows-end");
  }catch{file.Dispose();Parent?.Dispose();Parent=null;Leased.Clear();throw;}
 }
 private static int DisposalStarted;private static bool ParentWasOwned,ParentDisposeReturned,TicketWasOwned,TicketDisposeReturned;private static int LocalDisposed;
 internal static void Dispose(){if(Interlocked.Exchange(ref DisposalStarted,1)!=0)return;var errors=new List<Exception>();
  bool Release(IDisposable? value){if(value is null)return false;try{value.Dispose();return true;}catch(Exception ex){errors.Add(ex);return false;}}
  var parent=Parent;Parent=null;ParentWasOwned=parent is not null;ParentDisposeReturned=Release(parent);
  var ticket=Ticket;Ticket=null;TicketWasOwned=ticket is not null;TicketDisposeReturned=Release(ticket);
  foreach(var value in Local.Values)if(Release(value.Stream))++LocalDisposed;Local.Clear();Leased.Clear();
  if(errors.Count!=0)throw new AggregateException("binding-lease-disposal-failed",errors);
 }
 internal static object CleanupSnapshot()=>new{disposalStarted=Volatile.Read(ref DisposalStarted)!=0,parentWasOwned=ParentWasOwned,parentDisposeReturned=ParentDisposeReturned,ticketWasOwned=TicketWasOwned,ticketDisposeReturned=TicketDisposeReturned,localStreamsDisposed=LocalDisposed,remainingLocalStreams=Local.Count,parentFieldCleared=Parent is null,ticketFieldCleared=Ticket is null,meaning="Existing original ParentProcessLifetime.Dispose requests unregister and closes its owned wait handle. Unregister return is not exposed; this is disposal-call evidence, not proof of OS exit."};
 internal static object Snapshot()=>new{kind="INHERITED_NATIVE_READONLY_CONTENT_LEASE",ticketSha256=TicketHash,leasedPaths=Leased.Count,leaseHits=LeaseHits,localActualHashes=LocalHashes,localActualHashBytes=LocalBytes,parentAlive=Parent?.IsAlive??false,meaning="Hashes are actual native once-per-invocation content reads protected by held no-write/no-delete-share handles; unknown paths or dead parent fall back to real child hash+lock. Not per-child byte hashing."};
}

