using System.Diagnostics;
using System.Text.Json;
internal static class PrivateRuntimeTiming {
 private sealed record Point(string stage,long monotonicTicks,long elapsedTicks,long utcTicks,int managedThreadId);
 private static readonly List<Point> Points=new();
 private static string? Receipt;private static long Started,HashTicks,HashCalls;private static int Dropped;
 private static DateTime? SelfCreatedUtc;private static string? SelfCreatedFailure;
 internal static void Initialize(string receipt){if(Receipt is not null)throw new InvalidOperationException("timing-reentry");Receipt=receipt;Started=Stopwatch.GetTimestamp();Mark("entry-after-launch-guard");try{using var self=Process.GetCurrentProcess();SelfCreatedUtc=self.StartTime.ToUniversalTime();}catch(Exception ex){SelfCreatedFailure=ex.GetType().Name;}Mark("self-creation-time-read-end");}
 internal static void Mark(string stage){if(Receipt is null)return;var at=Stopwatch.GetTimestamp();if(Points.Count>=80){++Dropped;return;}Points.Add(new(stage,at,at-Started,DateTime.UtcNow.Ticks,Environment.CurrentManagedThreadId));}
 internal static void RecordHash(long start){if(Receipt is null)return;Interlocked.Add(ref HashTicks,Stopwatch.GetTimestamp()-start);Interlocked.Increment(ref HashCalls);}
 internal static void ProtocolMark(string kind,string? command){if((command=="HELLO"||command=="RELEASE_TARGET")&&(kind=="handle-begin"||kind=="handle-end"||kind=="pipe-write-end"))Mark("managed-"+command+"-"+kind);}
 internal static void WriteFinal(object cleanup){if(Receipt is null)return;Mark("diagnostic-write-begin");var report=new{schemaVersion=1,status="MANAGED_PHASE_TIMING_OBSERVATION",behaviorPass=(bool?)null,naturalExitObserved=(bool?)null,processId=Environment.ProcessId,selfCreatedUtc=SelfCreatedUtc,selfCreatedFailure=SelfCreatedFailure,stopwatchFrequency=Stopwatch.Frequency,startedAtTick=Started,hashCalls=HashCalls,hashElapsedTicks=HashTicks,droppedMarks=Dropped,points=Points.ToArray(),leaseCleanup=cleanup,source="Actual child monotonic/UTC observations. Self OS creation time is not CreateProcessW return duration. Protocol markers are managed handling, not native send/receive. Diagnostic sidecar write occurs after original receipt and is excluded from these phase durations."};using var stream=new FileStream(Receipt+".timing.json",FileMode.CreateNew,FileAccess.Write,FileShare.None);JsonSerializer.Serialize(stream,report);stream.Flush();}
}
